import math

def largest_prime_factor(n: int) -> int:
    def is_prime(k: int) -> bool:
        if k < 2:
            return False
        if k % 2 == 0:
            return k == 2
        limit = int(math.isqrt(k)) + 1
        for i in range(3, limit, 2):
            if k % i == 0:
                return False
        return True

    largest = 1
    # Check factors up to sqrt(n) and reduce n as we find prime factors
    temp = n
    # Remove factor 2
    while temp % 2 == 0:
        largest = 2
        temp //= 2
    # Check odd factors
    f = 3
    while f * f <= temp:
        while temp % f == 0:
            if is_prime(f):
                largest = f
            temp //= f
        f += 2
    # If remaining temp is > 1, it is a prime factor
    if temp > 1:
        largest = max(largest, temp)
    return largest
